import { EntityTrading } from '../EntityTrading/EntityTrading.sol';
import { IEntityTrading } from '../EntityTrading/IEntityTrading.sol';

contract Traittest is Test {
  TraitForgeNft traitForgeNft;
  EntityForging entityForging;
  EntropyGenerator entropyGenerator;
  NukeFund nukeFund;
  Airdrop airdrop;
  DevFund devFund;
  DAOFund daoFund;
  EntityTrading entityTrading;

  address owner = makeAddr('owner');
  address player1 = makeAddr('player1');
  address player2 = makeAddr('player2');

  function setUp() public {
    vm.startPrank(owner);

    // Deploy TraitForgeNft contract
    traitForgeNft = new TraitForgeNft();

    // Deploy Airdrop contract
    airdrop = new Airdrop();
    traitForgeNft.setAirdropContract(address(airdrop));
    airdrop.transferOwnership(address(traitForgeNft));

    // Deploy entropyGenerator contract
    entropyGenerator = new EntropyGenerator(address(traitForgeNft));
    // entropyGenerator.writeEntropyBatch1();
    // entropyGenerator.writeEntropyBatch2();
    // entropyGenerator.writeEntropyBatch3();
    traitForgeNft.setEntropyGenerator(address(entropyGenerator));

    // Deploy EntityForging contract
    entityForging = new EntityForging(address(traitForgeNft));
    traitForgeNft.setEntityForgingContract(address(entityForging));

    devFund = new DevFund();
    //daoFund = new DAOFund();
    nukeFund = new NukeFund(
      address(traitForgeNft),
      address(airdrop),
      payable(address(devFund)),
      payable(address(daoFund))
    );
    nukeFund.setAgeMultplier(1);
    traitForgeNft.setNukeFundContract(payable(address(nukeFund)));

    entityTrading = new EntityTrading(address(traitForgeNft));
    entityTrading.setNukeFundAddress(payable(address(nukeFund)));

    vm.stopPrank();

    vm.deal(player1, 2000 ether);
    vm.deal(player2, 10 ether);

    // Used to avoid whitelist proof
    skip(60 * 60 * 24 + 1);
    //vm.warp(86402);
    //vm.roll(86402);
  }

  function testmintprice() public {
    // Generating Entropies
    entropyGenerator.writeEntropyBatch1();
    entropyGenerator.writeEntropyBatch2();
    entropyGenerator.writeEntropyBatch3();

    // Proof
    bytes32[] memory argument = new bytes32[](1);
    argument[0] = keccak256(abi.encode('Hi'));

    // Fix required due to bug present in EntropyGenerator Contract
    vm.prank(owner);
    entropyGenerator.transferOwnership(address(traitForgeNft));

    // Minting 10000 gen 1 NFTs and 5 gen 2 NFTs
    vm.startPrank(player1);
    for (uint i = 0; i < 10005; i++) {
      // Prices of 10000 gen 1 NFTs
      if (i > 9994 && i < 10000) {
        console.log(
          'tokenId:',
          i + 1,
          'Price:',
          traitForgeNft.calculateMintPrice() / 1 gwei
        );
      }
      // Prices of 5 gen 2 NFTs
      // Gen 2 first NFT's price is 0.25 ETH rather than 0.005 ETH
      if (i >= 10000) {
        console.log(
          'new gen tokenId:',
          i - 10000 + 1,
          'Price:',
          traitForgeNft.calculateMintPrice() / 1 gwei
        );
      }
      traitForgeNft.mintToken{ value: 10 ether }(argument);
    }
    vm.stopPrank();
  }
}

```

