+    uint256 oldWeight = info.weight;
+    // Calculate allowed weight change range
+    uint256 maxIncrease = oldWeight + (oldWeight * MAX_WEIGHT_CHANGE_PERCENTAGE / 100);
+    uint256 maxDecrease = oldWeight - (oldWeight * MAX_WEIGHT_CHANGE_PERCENTAGE / 100);
+    require(newWeight >= maxDecrease && newWeight <= maxIncrease, "Weight change exceeds allowed range");
+    
+    totalDevWeight = totalDevWeight - oldWeight + newWeight;
     info.pendingRewards += (totalRewardDebt - info.rewardDebt) * info.weight;
