      let gen1Counter = await nft.generationMintCounts(1);
      let gen2Counter = await nft.generationMintCounts(2);
      console.log("Generation 1 NFT count:", gen1Counter);
      console.log("Generation 2 NFT count:", gen2Counter);
      expect(gen2Counter).to.be.eq(1n); // Proof that we have second generation NFTs

      // Get the initial max generation
      const initialMaxGen = await nft.maxGeneration();
      console.log("Initial max generation:", initialMaxGen);

      // Attempt to set max generation to 1
      try {
        const tx = await nft.connect(owner).setMaxGeneration(1n); //We will set maxGeneration to 1, although we have tokens of second generations as well
        await tx.wait(); // Wait for the transaction to be mined
